using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ARC.TiposArchivo;namespace GraphApi.Services.ARC.TiposArchivo{    public class TiposArchivoService : ITiposArchivoService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TiposArchivoService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTiposArchivo>> GetTiposArchivos(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM arc.TiposArchivo (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTiposArchivo>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTiposArchivosDynamic(            int? tipoArchivoID,            string? tipoArchivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TipoArchivoID, TipoArchivo, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM arc.TiposArchivo (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (tipoArchivoID.HasValue)            {                vSql.Append(" AND TipoArchivoID = @TipoArchivoID");                vParameters.Add("TipoArchivoID",tipoArchivoID);            }            if (!string.IsNullOrWhiteSpace(tipoArchivo))            {                vSql.Append(" AND TipoArchivo LIKE @TipoArchivo");                vParameters.Add("TipoArchivo",$"%{tipoArchivo}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTiposArchivo> CreateTiposArchivo(clCreateTiposArchivo objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO arc.TiposArchivo                (TipoArchivo, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TipoArchivo, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TipoArchivo,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TipoArchivoID, TipoArchivo, bEliminado                FROM arc.TiposArchivo (NOLOCK)                WHERE TipoArchivoID = @TipoArchivoID;";            var vReadParams = new { TipoArchivoID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTiposArchivo>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el TiposArchivo con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTiposArchivo?> UpdateTiposArchivo(clUpdateTiposArchivo objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TipoArchivoID", objInput.TipoArchivoID);            if (objInput.TipoArchivo is not null)            {                vSets.Add("TipoArchivo = @TipoArchivo");                vParameters.Add("TipoArchivo", objInput.TipoArchivo);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE arc.TiposArchivo                SET {vSetClause}                WHERE TipoArchivoID = @TipoArchivoID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TipoArchivoID, TipoArchivo, bEliminado                FROM arc.TiposArchivo (NOLOCK)                WHERE TipoArchivoID = @TipoArchivoID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTiposArchivo>(sSelect, new {  objInput.TipoArchivoID });        }        public async Task<bool> DeleteTiposArchivo(int nTiposArchivoID)        {            const string sSql = @"                DELETE FROM arc.TiposArchivo                WHERE TipoArchivoID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTiposArchivoID });            return vAffected > 0;        }    }}